9	const BASE_PREMIUMS = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	} as const satisfies Record<string, number>;
16	
17	type InsurableItemType = keyof typeof BASE_PREMIUMS;
18	
19	type Item = {
20	  type: InsurableItemType;
21	};
22	
23	type QuoteStep = {
24	  op: "quote";
25	  items: Item[];
26	};
27	
28	type Customer = {
29	  yearsWithMHPCO: number;
30	};
31	
32	type Scenario = {
33	  customer: Customer;
34	  steps: QuoteStep[];
35	};
36	
37	const PROCESSING_FEE = 5;
38	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
39	
40	const percentOf = (amount: number, percent: number): number =>
41	  (amount * percent) / 100;
42	
43	// The MHPCO always rounds in its own favour: premiums (which the customer
44	// pays) go up, payouts (which the MHPCO pays) go down.
45	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
46	
47	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
48	
49	const policyBasePremiumOf = (items: Item[]): number =>
50	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
51	
52	const quote = (step: QuoteStep): QuoteResult => {
53	  const basePremium = policyBasePremiumOf(step.items);
54	  const initialAssessmentSurcharge = percentOf(
55	    basePremium,
56	    INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
57	  );
58	
59	  return {
60	    premium: roundedInMHPCOsFavour(
61	      basePremium + initialAssessmentSurcharge + PROCESSING_FEE,
62	    ),
63	  };
64	};
65	
66	export const runScenario = (scenario: Scenario): ScenarioResult => {
67	  return { results: scenario.steps.map(quote) };
68	};
